package com.example.todo.controller; import com.example.todo.dto.*; import com.example.todo.service.AuthService; import jakarta.validation.Valid; import lombok.RequiredArgsConstructor; import org.springframework.http.*; import org.springframework.web.bind.annotation.*; @RestController @RequestMapping("/api/auth") @RequiredArgsConstructor public class AuthController {private final AuthService service;@PostMapping("/register") public ResponseEntity<AuthResponse> register(@Valid @RequestBody AuthRequest r){return ResponseEntity.status(HttpStatus.CREATED).body(service.register(r));}@PostMapping("/login") public AuthResponse login(@Valid @RequestBody AuthRequest r){return service.login(r);}}
